from common import Q
K="kids"
Q(K,1,"How many times do Muslims pray each day?","5",["3","2","10"],"We pray Fajr, Dhuhr, Asr, Maghrib and Isha.","Sahih al-Bukhari 349")
Q(K,1,"What do we say before we eat?","Bismillah",["Goodbye","Alhamdulillah","Ameen"],"We start with the name of Allah, and eat with our right hand.","Sahih al-Bukhari 5376")
Q(K,1,"What is the holy book of Muslims?","The Quran",["The Zabur","The Tawrah","A storybook"],"Allah sent the Quran to Prophet Muhammad ﷺ.","Quran 2:2")
Q(K,1,"Who is the last Prophet?","Muhammad ﷺ",["Isa","Musa","Nuh"],"Prophet Muhammad ﷺ is the Seal of the Prophets.","Quran 33:40")
Q(K,1,"In which month do Muslims fast?","Ramadan",["Shawwal","Muharram","Rajab"],"We fast from Fajr to Maghrib every day of Ramadan.","Quran 2:185")
Q(K,1,"In which city is the Kaaba?","Makkah",["Madinah","Cairo","Jerusalem"],"Muslims all over the world face the Kaaba when they pray.","Quran 3:96")
Q(K,1,"Which Prophet built the Ark?","Nuh",["Ibrahim","Yusuf","Dawud"],"Allah told Nuh to build a big ship before the flood.","Quran 11:37")
Q(K,1,"Which Prophet was swallowed by a big fish?","Yunus",["Musa","Sulayman","Adam"],"Yunus prayed to Allah inside the fish and Allah saved him.","Quran 37:139–144")
Q(K,1,"Which Prophet understood the speech of the ants?","Sulayman",["Nuh","Isa","Yaqub"],"Sulayman smiled when he heard an ant warn its friends.","Quran 27:18–19")
Q(K,1,"What do we say when we sneeze?","Alhamdulillah",["Bismillah","Assalamu alaykum","Ma sha Allah"],"Then the person who hears says 'Yarhamuk Allah'.","Sahih al-Bukhari 6224")
Q(K,1,"How do Muslims greet each other?","Assalamu alaykum",["Good morning only","Hello only","Goodbye"],"It means 'Peace be upon you.' Spreading salam brings love.","Sahih Muslim 54")
Q(K,1,"How do we reply to 'Assalamu alaykum'?","Wa alaykumus-salam",["Bismillah","Ameen","Thank you"],"We reply with an equal or better greeting.","Quran 4:86")
Q(K,1,"Which Prophet was thrown into a fire that became cool?","Ibrahim",["Musa","Yusuf","Isa"],"Allah said: 'O fire, be coolness and safety upon Ibrahim.'","Quran 21:69")
Q(K,1,"Which Prophet's staff turned into a snake?","Musa",["Harun","Nuh","Ismail"],"It was one of the signs Allah gave Musa before Fir'awn.","Quran 20:17–21")
Q(K,1,"Who built the Kaaba with Prophet Ibrahim?","His son Ismail",["Nuh","Musa","Yusuf"],"Father and son raised its walls and prayed to Allah.","Quran 2:127")
Q(K,1,"What is washing before prayer called?","Wudu",["Ghusl only","Tayammum","Iqamah"],"We wash our hands, mouth, nose, face, arms, wipe our head, and wash our feet.","Quran 5:6")
Q(K,1,"What is the call to prayer called?","Adhan",["Dua","Dhikr","Khutbah"],"The muezzin calls the adhan five times a day.","Sahih al-Bukhari 604")
Q(K,1,"Where do Muslims pray together?","The masjid",["The market","The library","The park only"],"The masjid is the house of Allah.","Quran 9:18")
Q(K,1,"Which Eid comes after Ramadan?","Eid al-Fitr",["Eid al-Adha","Ashura","Mawlid"],"On Eid al-Fitr we thank Allah after a month of fasting.","Sunan Abi Dawud 1134")
Q(K,1,"Which Eid is the festival of sacrifice?","Eid al-Adha",["Eid al-Fitr","Laylat al-Qadr","Jumu'ah"],"It remembers Prophet Ibrahim's obedience to Allah.","Quran 37:102–107")
Q(K,1,"Which angel brought Allah's message to the Prophets?","Jibril",["Mika'il","Israfil","Malik"],"Jibril brought the Quran to Prophet Muhammad ﷺ.","Quran 2:97")
Q(K,1,"How many pillars of Islam are there?","5",["3","4","6"],"Shahadah, salah, zakat, fasting and Hajj.","Sahih al-Bukhari 8")
Q(K,1,"What is the first pillar of Islam?","The Shahadah",["Fasting","Hajj","Zakat"],"La ilaha illallah, Muhammadur Rasulullah.","Sahih al-Bukhari 8")
Q(K,1,"What was the name of the Prophet's daughter who married Ali?","Fatimah",["Aishah","Khadijah","Maryam"],"Fatimah az-Zahra was very beloved to the Prophet ﷺ.","Sahih al-Bukhari 3714")
Q(K,1,"Which Prophet dreamed of eleven stars, the sun and the moon?","Yusuf",["Yaqub","Ibrahim","Musa"],"Yusuf told his father about the dream when he was a boy.","Quran 12:4")
Q(K,1,"In which city is Prophet Muhammad ﷺ buried?","Madinah",["Makkah","Ta'if","Jerusalem"],"His blessed resting place is in Masjid an-Nabawi.","Sunan at-Tirmidhi 1018")
Q(K,1,"On which day is the Jumu'ah prayer?","Friday",["Monday","Sunday","Wednesday"],"Friday is the best day of the week.","Sahih Muslim 854")
Q(K,1,"What does 'SubhanAllah' mean?","Glory be to Allah",["Thank you","If Allah wills","Allah is the Greatest"],"We say it when we see something amazing Allah has made.","Sahih Muslim 2694")
Q(K,1,"What does 'Alhamdulillah' mean?","All praise is for Allah",["Peace be upon you","Goodbye","In the name of Allah"],"We thank Allah for everything He gives us.","Quran 1:2")
Q(K,1,"What does 'In sha Allah' mean?","If Allah wills",["Thank you","Glory be to Allah","Excuse me"],"We say it when we talk about doing something in the future.","Quran 18:23–24")
Q(K,1,"Which animal did the people of Prophet Salih harm?","A she-camel",["A cow","A sheep","A horse"],"The she-camel was a sign from Allah, and they were told not to harm it.","Quran 91:13–14")
Q(K,1,"Which Prophet was given the Zabur?","Dawud",["Musa","Isa","Sulayman"],"Dawud praised Allah beautifully, and the mountains and birds praised with him.","Quran 4:163; 34:10")
Q(K,1,"Who was the mother of Prophet Isa?","Maryam",["Hajar","Asiyah","Sarah"],"Maryam was a very righteous woman chosen by Allah.","Quran 3:42")
Q(K,1,"Who was the first muezzin?","Bilal",["Abu Bakr","Umar","Zayd"],"Bilal had a beautiful voice and called the adhan for the Prophet ﷺ.","Sunan Abi Dawud 499")
Q(K,1,"What should we say to someone who helps us?","Jazak Allahu khayran",["Inna lillah","Astaghfirullah","Nothing"],"It means 'May Allah reward you with good.'","Sunan at-Tirmidhi 2035")
